import subprocess,sys
def istok(e):
    p=subprocess.run(['/workspace/executable','-n','--expression',e],capture_output=True,text=True)
    err=p.stderr.strip()
    if 'lexer: invalid input text' in err: return ('NO',err)
    return ('YES',err or p.stdout.strip().replace('\n',' '))
names=sys.argv[1:]
for n in names:
    r=istok(n)
    print('%-24s %s %s' % (n, r[0], r[1][:90]))
